    primes = [i for i in range(2, int(a**0.5) + 1) if is_prime(i)]

    # Check all possible combinations of three prime numbers
    for i in primes:
        for j in primes:
            if a % (i * j) == 0 and is_prime(a // (i * j)):
                return True

    return False


