import heapq

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    pq = []
    visited = set()

    for i in range(n):
        for j in range(n):
            heapq.heappush(pq, (grid[i][j], i, j, [(i, j)]))

    while pq:
        val, x, y, path = heapq.heappop(pq)
        if (x, y) in visited:
            continue
        visited.add((x, y))

        if len(path) == k:
            return [grid[i][j] for i, j in path]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [(nx, ny)]
                heapq.heappush(pq, (val, nx, ny, new_path))
